import{_ as a,o as d,c as r,a3 as e}from"./chunks/framework.BM_-pWjS.js";const o="/bridge-lite/manual/assets/filter.wKQWnRgo.png",f=JSON.parse('{"title":"フィルター","description":"","frontmatter":{},"headers":[],"relativePath":"ja/filter-spec.md","filePath":"ja/filter-spec.md"}'),h={name:"ja/filter-spec.md"};function i(l,t,n,s,p,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="フィルター" tabindex="-1">フィルター <a class="header-anchor" href="#フィルター" aria-label="Permalink to &quot;フィルター&quot;">​</a></h1><p>左サイドバーに表示されるフィルターを使用すると、表示する写真を絞り込むことができます。フィルターパネル上部のトグルでグループを解除する<a href="./flat.html">フラット化</a>も利用できます。</p><p><img src="'+o+'" alt="フィルターパネル"></p><h2 id="file-type-ファイル種別" tabindex="-1">FILE TYPE（ファイル種別） <a class="header-anchor" href="#file-type-ファイル種別" aria-label="Permalink to &quot;FILE TYPE（ファイル種別）&quot;">​</a></h2><p>グルーピングを主機能とする bridge-lite 独自の概念です。各グループの「代表写真」を、ファイル種別によって切り替えます。</p><table tabindex="0"><thead><tr><th>種別</th><th>説明</th></tr></thead><tbody><tr><td>カメラ出力</td><td>カメラが生成した JPEG（SOOC）</td></tr><tr><td>RAW</td><td>RAW ファイル</td></tr><tr><td>現像済み</td><td>Lightroom 等で現像した JPEG / TIFF</td></tr><tr><td>判定不能</td><td>上記いずれにも分類できないファイル</td></tr></tbody></table><p>チェックを入れた種別のみがグループの代表として表示されます。複数チェックした場合は <strong>現像済み &gt; カメラ出力 &gt; RAW</strong> の優先順位で上位の種別が代表になります。</p><p><strong>カメラ撮影のみ</strong> にチェックを入れると、EXIF 情報を持たない写真（スクリーンショット等）を除外します。</p><h3 id="使用例" tabindex="-1">使用例 <a class="header-anchor" href="#使用例" aria-label="Permalink to &quot;使用例&quot;">​</a></h3><p>10 枚の写真があり、カメラ出力で満足できるものが 5 枚、現像したいものが 5 枚あったとします。Lightroom 等で現像したファイルをフォルダに取り込んだあと、「カメラ出力」と「現像済み」の両方にチェックを入れると、現像済みのものはそちらを、残りはカメラ出力を代表として 10 枚を一覧できます。</p><h2 id="メタデータによる絞り込み-チェックボックス" tabindex="-1">メタデータによる絞り込み（チェックボックス） <a class="header-anchor" href="#メタデータによる絞り込み-チェックボックス" aria-label="Permalink to &quot;メタデータによる絞り込み（チェックボックス）&quot;">​</a></h2><p>取り込んだ写真の EXIF 情報をもとに絞り込みます。</p><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>カメラ</td><td>使用したカメラ機種で絞り込む</td></tr><tr><td>フォトグラファー</td><td>撮影者で絞り込む</td></tr><tr><td>レンズ</td><td>使用したレンズで絞り込む</td></tr><tr><td>評価</td><td>星評価で絞り込む</td></tr><tr><td>ラベル</td><td>ラベルで絞り込む</td></tr></tbody></table><h2 id="メタデータによる絞り込み-ヒストグラム" tabindex="-1">メタデータによる絞り込み（ヒストグラム） <a class="header-anchor" href="#メタデータによる絞り込み-ヒストグラム" aria-label="Permalink to &quot;メタデータによる絞り込み（ヒストグラム）&quot;">​</a></h2><p>取り込んだ写真の EXIF 情報をもとに、数値範囲で絞り込みます。分布がヒストグラムで表示されるため、どの焦点距離をよく使うかなど撮影傾向の把握にも活用できます。</p><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>ISO</td><td>ISO 感度で絞り込む</td></tr><tr><td>焦点距離</td><td>焦点距離で絞り込む</td></tr><tr><td>シャッター</td><td>シャッタースピードで絞り込む</td></tr><tr><td>絞り</td><td>絞り値（F 値）で絞り込む</td></tr><tr><td>撮影日時</td><td>撮影日時で絞り込む</td></tr><tr><td>彩度</td><td>彩度で絞り込む</td></tr></tbody></table><h2 id="その他の操作" tabindex="-1">その他の操作 <a class="header-anchor" href="#その他の操作" aria-label="Permalink to &quot;その他の操作&quot;">​</a></h2><h3 id="フィルターの折りたたみ" tabindex="-1">フィルターの折りたたみ <a class="header-anchor" href="#フィルターの折りたたみ" aria-label="Permalink to &quot;フィルターの折りたたみ&quot;">​</a></h3><p>各フィルターのタイトル右側にある矢印をクリックすると、そのフィルターを折りたたんだり展開したりできます。使用しないフィルターを畳んでおくと、サイドバーをすっきり使えます。</p><h3 id="フィルターの並び順の変更" tabindex="-1">フィルターの並び順の変更 <a class="header-anchor" href="#フィルターの並び順の変更" aria-label="Permalink to &quot;フィルターの並び順の変更&quot;">​</a></h3><p>設定画面でフィルターの表示順を入れ替えられます。よく使うフィルターを上に移動しておくと便利です。</p>',21)])])}const m=a(h,[["render",i]]);export{f as __pageData,m as default};
